package fixture

import "testing"

func TestSumTo(t *testing.T) {
	cases := map[int]int{0: 0, 1: 1, 4: 10, 10: 55}
	for n, want := range cases {
		if got := SumTo(n); got != want {
			t.Fatalf("SumTo(%d) = %d, want %d", n, got, want)
		}
	}
}

