package ratelimit

import "time"

// Limiter admits at most Burst events per Window using a fixed window.
type Limiter struct {
	Burst  int
	Window time.Duration
	count  int
	start  time.Time
	now    func() time.Time
}

// New returns a Limiter that admits burst events per window.
func New(burst int, window time.Duration) *Limiter {
	return &Limiter{Burst: burst, Window: window, now: time.Now}
}

// Allow reports whether one more event fits in the current window and
// counts it if so. Once Burst events were admitted, Allow returns false
// until the window elapses and the counter resets.
func (l *Limiter) Allow() bool {
	t := l.now()
	if l.start.IsZero() || t.Sub(l.start) >= l.Window {
		l.start, l.count = t, 0
	}
	if l.count >= l.Burst {
		return false
	}
	l.count++
	return true
}

